CREATE OR REPLACE FUNCTION public.sb_record_attempt(p_student uuid, p_problem uuid, p_expected integer, p_next jsonb, p_blocks jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  student_row public.sb_students%rowtype;
  problem_row public.sb_problems%rowtype;
  previous public.sb_problem_attempts%rowtype;
  total integer;
  done integer;
  star_count integer;
begin
  select * into strict student_row from public.sb_students where id=p_student for update;
  if student_row.status <> 'active' then raise exception 'STUDENT_DISABLED'; end if;
  select * into strict problem_row from public.sb_problems where id=p_problem and active
    and (class_id is null or class_id=student_row.class_id);
  if coalesce((select locked from public.sb_lesson_settings where class_id=student_row.class_id and lesson=problem_row.lesson),problem_row.lesson<>1)
    then raise exception 'LESSON_LOCKED'; end if;
  select * into previous from public.sb_problem_attempts where student_id=p_student and problem_id=p_problem;
  if coalesce(previous.attempt_count,0)<>p_expected then raise exception 'ATTEMPT_CONFLICT'; end if;
  if previous.completed then return; end if;
  insert into public.sb_problem_attempts(student_id,problem_id,lesson,wrong_count,hint_shown,answer_revealed,completed,attempt_count,stars,xp_earned,completed_at)
  values(p_student,p_problem,problem_row.lesson,(p_next->>'wrongCount')::integer,(p_next->>'hintShown')::boolean,(p_next->>'answerRevealed')::boolean,
    (p_next->>'completed')::boolean,p_expected+1,(p_next->>'stars')::integer,(p_next->>'xp')::integer,
    case when (p_next->>'completed')::boolean then now() else null end)
  on conflict(student_id,problem_id) do update set
    wrong_count=excluded.wrong_count,hint_shown=excluded.hint_shown,answer_revealed=excluded.answer_revealed,completed=excluded.completed,
    attempt_count=excluded.attempt_count,stars=excluded.stars,xp_earned=excluded.xp_earned,completed_at=excluded.completed_at,updated_at=now();
  if p_blocks is not null then
    insert into public.sb_block_snapshots(student_id,problem_id,lesson,blocks,grid_width,grid_depth,max_height)
    values(p_student,p_problem,problem_row.lesson,p_blocks,problem_row.grid_width,problem_row.grid_depth,problem_row.max_height)
    on conflict(student_id,problem_id) do update set blocks=excluded.blocks,updated_at=now();
  end if;
  select count(*) into total from public.sb_problems where lesson=problem_row.lesson and active and (class_id is null or class_id=student_row.class_id);
  select count(*) filter(where a.completed), coalesce(sum(a.stars),0) into done,star_count from public.sb_problem_attempts a
    join public.sb_problems p on p.id=a.problem_id where a.student_id=p_student and p.lesson=problem_row.lesson and p.active and (p.class_id is null or p.class_id=student_row.class_id);
  insert into public.sb_student_progress(student_id,lesson,completed,completed_at,stars,last_problem_id)
  values(p_student,problem_row.lesson,total>0 and done=total,case when total>0 and done=total then now() else null end,star_count,p_problem)
  on conflict(student_id,lesson) do update set completed=excluded.completed,completed_at=excluded.completed_at,stars=excluded.stars,last_problem_id=excluded.last_problem_id,updated_at=now();
  insert into public.sb_student_rewards(student_id,total_xp,total_stars)
  select p_student,coalesce(sum(xp_earned),0),coalesce(sum(stars),0) from public.sb_problem_attempts where student_id=p_student
  on conflict(student_id) do update set total_xp=excluded.total_xp,total_stars=excluded.total_stars,updated_at=now();
end;
$function$

CREATE OR REPLACE FUNCTION public.sb_reset_progress(p_student uuid, p_lesson integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 if not public.sb_owns_student(p_student) then raise exception 'FORBIDDEN_STUDENT'; end if;
 if p_lesson is not null and (p_lesson<1 or p_lesson>12) then raise exception 'BAD_LESSON'; end if;
 perform 1 from public.sb_students where id=p_student for update;
 delete from public.sb_problem_attempts where student_id=p_student and (p_lesson is null or lesson=p_lesson);
 delete from public.sb_block_snapshots where student_id=p_student and (p_lesson is null or lesson=p_lesson);
 delete from public.sb_student_progress where student_id=p_student and (p_lesson is null or lesson=p_lesson or (p_lesson in (10,11) and lesson in (10,11)));
 if p_lesson is null or p_lesson=9 then delete from public.sb_challenge_solves where student_id=p_student; end if;
 if p_lesson is null or p_lesson in (10,11) then delete from public.sb_projects where student_id=p_student; end if;
 if p_lesson is null or p_lesson=12 then delete from public.sb_self_evaluations where student_id=p_student; end if;
 insert into public.sb_student_rewards(student_id,total_xp,total_stars)
 select p_student,coalesce(sum(xp_earned),0),coalesce(sum(stars),0) from public.sb_problem_attempts where student_id=p_student
 on conflict(student_id) do update set total_xp=excluded.total_xp,total_stars=excluded.total_stars,badges='[]',streak=0;
end; $function$

CREATE OR REPLACE FUNCTION public.sb_save_building(p_student uuid, p_class uuid, p_version integer, p_data jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare current_version integer; next_version integer;
begin
 perform 1 from public.sb_students where id=p_student and class_id=p_class and status='active' for update;
 if not found then raise exception 'FORBIDDEN_STUDENT'; end if;
 select version into current_version from public.sb_projects where student_id=p_student;
 if coalesce(current_version,0)<>p_version then raise exception 'VERSION_CONFLICT'; end if;
 next_version:=coalesce(current_version,0)+1;
 insert into public.sb_projects(student_id,class_id,building_name,reason,description,layer_notes,blocks,grid_width,grid_depth,max_height,submitted,version)
 values(p_student,p_class,p_data->>'building_name',p_data->>'reason',p_data->>'description',p_data->'layer_notes',p_data->'blocks',5,5,3,(p_data->>'submitted')::boolean,next_version)
 on conflict(student_id) do update set building_name=excluded.building_name,reason=excluded.reason,description=excluded.description,layer_notes=excluded.layer_notes,blocks=excluded.blocks,submitted=excluded.submitted,version=excluded.version;
 if (p_data->>'submitted')::boolean then
   insert into public.sb_student_progress(student_id,lesson,completed,completed_at,stars) values(p_student,10,true,now(),1),(p_student,11,true,now(),1)
   on conflict(student_id,lesson) do update set completed=true,completed_at=now(),stars=1;
 end if;
 return next_version;
end; $function$

CREATE OR REPLACE FUNCTION public.sb_submit_challenge(p_student uuid, p_challenge uuid, p_previous integer, p_state jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare current_wrong integer;
begin
 perform 1 from public.sb_students s join public.sb_shared_challenges c on c.class_id=s.class_id where s.id=p_student and c.id=p_challenge and s.status='active' for update of s;
 if not found then raise exception 'FORBIDDEN_CLASS'; end if;
 select wrong_count into current_wrong from public.sb_challenge_solves where student_id=p_student and challenge_id=p_challenge;
 if coalesce(current_wrong,0)<>p_previous then raise exception 'VERSION_CONFLICT'; end if;
 insert into public.sb_challenge_solves(challenge_id,student_id,correct,used_hint,wrong_count,answer_revealed,xp)
 values(p_challenge,p_student,(p_state->>'completed')::boolean,(p_state->>'hintShown')::boolean,(p_state->>'wrongCount')::integer,(p_state->>'answerRevealed')::boolean,(p_state->>'xp')::integer)
 on conflict(challenge_id,student_id) do update set correct=excluded.correct,used_hint=excluded.used_hint,wrong_count=excluded.wrong_count,answer_revealed=excluded.answer_revealed,xp=excluded.xp,solved_at=now()
 where not sb_challenge_solves.correct;
 if (p_state->>'completed')::boolean then
 insert into public.sb_student_progress(student_id,lesson,completed,completed_at,stars) values(p_student,9,true,now(),1)
 on conflict(student_id,lesson) do update set completed=true,completed_at=now(),stars=1;
 end if;
end; $function$

CREATE OR REPLACE FUNCTION public.sb_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
